(() => {
'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=(x,d=0)=>x==null?'—':new Intl.NumberFormat('tr-TR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(x);
const groups={UC_BUYUK_IL:'İstanbul / Ankara / İzmir',DIGER_ILLER:'Diğer iller'};
const name=g=>groups[g]||g;
function resolveCase(data,state){
 if(!data.parameter_grid)return data;
 const auto=data.automatic_selection,grid=data.parameter_grid,caseId=state.clusterScenario||auto?.decision.selected?.case_id||grid.selected_case_id;
 const item=grid.cases.find(c=>c.case_id===caseId)||grid.cases.find(c=>c.case_id===grid.selected_case_id);
 return {...item.report,method_names:data.method_names,matches_current_selection:data.matches_current_selection,automatic_selection:auto,dea_available:data.dea_available,viewed_case_id:item.case_id,display_primary_method:auto?(auto.decision.selected?.method||null):item.report.manifest.primary_method};
}
window.resolveClusteringData=resolveCase;
function gridPanel(data,state){
 const grid=data.parameter_grid;if(!grid)return '';
 const auto=data.automatic_selection,w=auto?.decision.selected;const chosen=state.clusterScenario||w?.case_id||grid.selected_case_id;
 return `<section class="card space-bottom"><div class="card-head"><div><h2>Alan oranı × toplam küme sayısı denemeleri</h2><p>Alan seçimi orijinal önem sırasına göre; mtry ise kodlama sonrası RF sütun sayısının %${nf(grid.mtry_ratio*100)}'i. mtry aşağı, alan sayısı yukarı yuvarlanır.</p></div></div><div class="card-body text-detail"><p>Ortak değerlendirme bütün senaryolarda aynı ${nf(grid.parent_feature_count)} alanlı Gower uzaklığıyla yapılır. ${auto?`Performansa göre güncel ortak seçim: <strong>${w?esc(data.method_names[w.method])+' · '+esc(w.case_id):'uygun model yok'}</strong>. Seçim dönemleri ve eleme koşulları <a href="#model-selection">Ana model seçimi</a> ekranındadır.`:`Önceki URF referans seçimi: <strong>${esc(grid.selected_case_id)}</strong>.`} Bu tablonun yeniden kümeleme ARI değerleri bütün izleme aylarının tarihsel özetidir; otomatik seçim puanı değildir.</p><label class="local-select">İncelenecek senaryo<select id="cluster-scenario">${grid.cases.map(c=>`<option value="${esc(c.case_id)}" ${c.case_id===chosen?'selected':''}>%${nf(c.feature_ratio*100)} alan · ${c.feature_count} değişken · toplam ${c.bank_clusters} küme${c.case_id===grid.selected_case_id?' · referans seçimi':''}</option>`).join('')}</select></label><p>Seçilen %25/%50 listelerinde kategorik alan kalmazsa K-Prototypes uygulanamaz. Alan oranını korumak için sonradan bir kategorik alan eklenmez.</p>${grid.selection_status==='exploratory_size_review'?'<p class="inline-note">Hiçbir URF senaryosu bütün boyut koşullarını sağlamadı. Seçim keşif amaçlıdır; DEA öncesi inceleme gerekir.</p>':''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Senaryo / yöntem</th><th class="num">Ham alan</th><th class="num">Toplam küme</th><th class="num">Kodlanmış sütun</th><th class="num">mtry</th><th class="num">Ortak referans puanı</th><th class="num">Yeniden kümeleme ARI</th><th>Boyut kontrolü</th></tr></thead><tbody>${grid.bank_scores.map(r=>{const c=grid.cases.find(c=>c.case_id===r.case_id);return `<tr><td>${esc(r.case_id)} · ${esc(data.method_names[r.method])}${w&&r.case_id===w.case_id&&r.method===w.method?'<span class="badge success">Ana model</span>':''}<span class="sub">${Object.entries(c.k_by_group).map(([g,k])=>esc(name(g))+': '+k).join(' · ')}</span></td><td class="num">${c.feature_count}</td><td class="num">${r.bank_clusters}</td><td class="num">${r.encoded_feature_counts?.join(' / ')||'—'}</td><td class="num">${r.effective_mtry_values?.join(' / ')||'—'}</td><td class="num">${nf(r.reference_score,3)}</td><td class="num">${nf(r.mean_refit_ari,3)}</td><td>${!r.applicable?'Uygulanamaz: karma veri yok':r.size_feasible?'Pilot sınırı geçti':'İnceleme gerekli'}</td></tr>`;}).join('')}</tbody></table></div><div class="card-body"><a class="button secondary small" href="downloads/clustering_grid_scores.csv" download>Bütün senaryo puanlarını indir</a></div></section>`;
}
function filters(data,state){return {group:state.clusterGroup||'ALL',method:state.clusterMethod||data.display_primary_method||data.manifest.primary_method,period:state.clusterPeriod||data.manifest.as_of};}
function assignmentRows(data,state){const f=filters(data,state);return data.assignments.filter(r=>r.mode==='frozen'&&r.method===f.method&&r.__period===f.period&&(f.group==='ALL'||r.__group===f.group)&&(!state.clusterSearch||(r.__branch+' '+r.cluster_id).toLocaleLowerCase('tr').includes(state.clusterSearch.toLocaleLowerCase('tr'))));}
function profiles(data,group,method,period){
 const rows=data.profiles.filter(r=>r.group===group&&r.method===method&&r.period===period),clusters=[...new Set(rows.map(r=>r.cluster))].sort((a,b)=>a-b);
 return `<section class="card space-bottom"><div class="card-head"><div><h2>${esc(name(group))} · küme profilleri</h2><p>Sayısal alanlarda kaynak biriminde medyan; kategorik alanlarda en yaygın değer ve payı. Temsilciler referans aya aittir.</p></div></div><div class="table-wrap cluster-profile"><table class="data-table"><thead><tr><th>Alan</th>${clusters.map(c=>{const r=rows.find(r=>r.cluster===c);return `<th class="num">C${c+1} · ${r.n} şube<span class="sub">Referans temsilcisi ${esc(r.representative_branch_id||'—')}</span></th>`;}).join('')}</tr></thead><tbody>${data.selected_schema.fields.map(field=>`<tr><td>${esc(field.label||field.name)}<span class="sub mono">${esc(field.name)}</span></td>${clusters.map(c=>{const values=rows.filter(r=>r.cluster===c&&r.feature===field.name);const r=values[0];if(!r)return '<td>—</td>';if(field.dtype==='numeric')return `<td class="num">${nf(r.median,3)}</td>`;const top=[...values].sort((a,b)=>b.share-a.share||a.category.localeCompare(b.category))[0];return `<td class="num">${esc(top.category)} · %${nf(top.share*100,1)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></section>`;
}
window.renderClusteringPage=(data,state)=>{
 if(!data)return '<section class="card"><div class="card-body">Kümeleme çalışması henüz yüklenmedi.</div></section>';
 const grid=gridPanel(data,state);data=resolveCase(data,state);
 const m=data.manifest,auto=data.automatic_selection,w=auto?.decision.selected,primary=auto?(w?.method||null):m.primary_method,isPrimaryCase=!auto||w?.case_id===data.viewed_case_id,f=filters(data,state),visibleGroups=f.group==='ALL'?m.groups:[f.group];
 const rows=data.summary.filter(r=>visibleGroups.includes(r.group));
 const current=data.assignments.filter(r=>r.mode==='frozen'&&r.method===f.method&&r.__period===f.period&&visibleGroups.includes(r.__group));
 const searched=assignmentRows(data,state),selected=data.selected.filter(r=>r.method===f.method&&visibleGroups.includes(r.group));
 const clusterCount=new Set(current.map(r=>r.cluster_id)).size;
 const periods=[m.reference_period,m.as_of];
 const monthRows=data.monthly.filter(r=>r.method===f.method&&visibleGroups.includes(r.group)&&r.mode==='frozen');
 return `<div class="clustering-page">${grid}<div class="clustering-intro"><div><span class="badge model">${primary?'Ana yöntem: '+esc(data.method_names[primary]):'Uygun ana model yok'}${primary&&!isPrimaryCase?' · bu senaryo yalnızca inceleme':''}</span><h2>Şube kümeleri ve alternatif karşılaştırması</h2><p>Referans ${esc(m.reference_period)} · son ay ${esc(m.as_of)} · ${nf(m.feature_count)} ortak alan. Üç üretim göstergesi aynı kümeleri kullanır.</p></div><a class="button secondary" href="${auto?'downloads/auto_cluster_methodology.md':'downloads/clustering_methodology.md'}" download>Metodolojiyi indir</a></div>${m.not_applicable.length?`<p class="inline-note">${m.not_applicable.map(r=>esc(name(r.group))+": "+esc(data.method_names[r.method])+" — "+esc(r.reason)).join("; ")}</p>`:""}${data.matches_current_selection===false?'<p class="inline-note">Bu kümeler önceki değişken şemasıyla oluşturuldu; son seçim çalışmasıyla şema sürümleri farklı.</p>':''}<div class="kpi-grid">${[['İncelenen şube',current.length,'Seçili yöntem, grup ve dönem'],['Seçili görünümde küme',clusterCount,'Grupların kendi kümeleri'],['Ortak girdi',m.feature_count,'Stoklar ve üretim toplamları kullanılmadı'],['Uygulanabilen yöntem',new Set(data.selected.map(r=>r.method)).size,'Ana model performans koşullarıyla seçilir']].map(([label,value,detail])=>`<div class="kpi"><div class="kpi-head">${label}</div><div class="kpi-value">${nf(value)}</div><small>${detail}</small></div>`).join('')}</div><section class="card space-bottom"><div class="card-body text-detail"><p><strong>${data.dea_available?'Seçilen ana modelin DEA analizi tamamlandı; hedef dağıtımı sırada.':auto&&!w?'Kümeleme adayları hesaplandı; güncel politikaya göre uygun ana model yok.':'Kümeler oluşturuldu; bu seçim için DEA henüz yapılmadı.'}</strong> ${auto?`Güncel ana model: ${w?esc(data.method_names[w.method])+' · '+esc(w.case_id):'uygun model yok'}. Yöntem ve senaryo kalite koşullarına göre otomatik seçilir.`:'Bu ekran önceki URF başlangıç karşılaştırmasıdır.'}</p><p>Referans modelleri sabittir; otomatik yöntemde ortak k senaryosu doğrulama dönemleriyle birlikte seçilir. Sabit referansla aylık atama ve her ay yeniden kümeleme ayrı ölçüldü. Yüksek kararlılık sabit bölgesel alanlardan da kaynaklanabilir; müşteri profilleri birlikte incelenmelidir.</p><p>Küme başına ${nf(data.settings.min_cluster_size)} şube pilot kontrol sınırıdır; DEA yeterliliği girdi/çıktı boyutlarıyla ayrıca değerlendirilecek.</p></div></section><div class="cluster-controls"><label>Yöntem<select id="cluster-method">${m.methods.map(method=>`<option value="${esc(method)}" ${method===f.method?'selected':''} ${data.selected.some(r=>r.method===method)?'':'disabled'}>${esc(data.method_names[method])}${data.selected.some(r=>r.method===method)?'':' · uygulanamaz'}${method===primary&&isPrimaryCase?' · ana yöntem':''}</option>`).join('')}</select></label><label>Şube grubu<select id="cluster-group"><option value="ALL">Tüm şubeler</option>${m.groups.map(g=>`<option value="${esc(g)}" ${g===f.group?'selected':''}>${esc(name(g))}</option>`).join('')}</select></label><label>Profil dönemi<select id="cluster-period">${periods.map(p=>`<option value="${p}" ${p===f.period?'selected':''}>${p}${p===m.reference_period?' · referans':' · son ay'}</option>`).join('')}</select></label></div><section class="card space-bottom"><div class="card-head"><div><h2>Yöntemlerin aynı girdilerle karşılaştırması</h2><p>Silhouette bütün yöntemlerde aynı ${nf((m.common_evaluation_features||m.features).length)} alanlı referans Gower matrisiyle hesaplandı. Bu ölçü Gower geometrisini tercih edebilir; tek başına üstünlük kanıtı değildir.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Yöntem / grup</th><th class="num">k</th><th>Referans büyüklükleri</th><th>Son ay büyüklükleri</th><th class="num">Ortak silhouette</th><th class="num">Aylık yeniden kümeleme ARI</th><th class="num">Alt örneklem ARI</th><th class="num">Tohum ARI</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(data.method_names[r.method])}${r.method===primary&&isPrimaryCase?'<span class="badge success">Ana yöntem</span>':''}<span class="sub">${esc(name(r.group))}</span></td><td class="num">${r.k}</td><td>${r.cluster_sizes.join(' / ')}</td><td>${r.latest_frozen_sizes.join(' / ')}${r.latest_size_rule_passed?'':'<span class="sub">Boyut kontrolü gerekli</span>'}</td><td class="num">${nf(r.common_gower_silhouette,3)}</td><td class="num">${nf(r.mean_refit_ari,3)}</td><td class="num">${nf(r.mean_subsample_ari,3)}</td><td class="num">${nf(r.mean_seed_ari,3)}</td></tr>`).join('')}</tbody></table></div></section><div class="group-panels">${selected.map(s=>{const members=current.filter(r=>r.__group===s.group),counts=Array.from({length:s.k},(_,c)=>members.filter(r=>r.cluster===c).length),max=Math.max(...counts,1);return `<section class="card"><div class="card-head"><div><h2>${esc(name(s.group))} · ${esc(data.method_names[f.method])}</h2><p>${f.period} · ${members.length} şube · ${s.k} küme</p></div></div><div class="card-body">${counts.map((n,c)=>`<div class="cluster-size-row"><span>C${c+1}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%;background:${f.method==='urf_kmedoids'?'#318975':'#557ca4'}"></div></div><strong>${n} şube</strong></div>`).join('')}</div></section>`;}).join('')}</div><section class="card space-bottom"><div class="card-head"><div><h2>Aylık atama ve yeniden kümeleme kararlılığı</h2><p>ARI etiket numaralarından bağımsızdır; yüksek değer daha benzer bölünme demektir. Değişim oranı etiketler örtüşmeye göre eşleştirildikten sonra hesaplanır.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Grup</th><th>Ay</th><th class="num">Sabit atama ARI</th><th class="num">Yeniden kümeleme ARI</th><th class="num">Yeniden kümelemede değişim</th><th>Sabit atama büyüklükleri</th></tr></thead><tbody>${monthRows.map(r=>{const other=data.monthly.find(x=>x.group===r.group&&x.method===r.method&&x.period===r.period&&x.mode==='monthly_refit');return `<tr><td>${esc(name(r.group))}</td><td>${r.period}</td><td class="num">${nf(r.ari,3)}</td><td class="num">${nf(other.ari,3)}</td><td class="num">%${nf(other.aligned_switch_fraction*100,1)}</td><td>${r.cluster_sizes.join(' / ')}</td></tr>`;}).join('')}</tbody></table></div></section>${visibleGroups.map(g=>profiles(data,g,f.method,f.period)).join('')}<section class="card space-bottom"><div class="card-head"><div><h2>Şube küme atamaları</h2><p>${esc(data.method_names[f.method])} · ${f.period} · ${nf(searched.length)} kayıt. Kümeler hedef veya verimlilik skoru değildir.</p></div><button id="export-clustering" class="button secondary small">Seçili atamaları indir</button></div><div class="cluster-controls"><label>Şube veya küme ara<input id="cluster-search" type="search" value="${esc(state.clusterSearch||'')}" placeholder="Şube kodu veya küme"></label></div><div class="table-wrap cluster-assignments"><table class="data-table"><thead><tr><th>Şube</th><th>Grup</th><th>Küme</th><th>Referans temsilcisi</th></tr></thead><tbody>${searched.length?searched.map(r=>{const p=data.profiles.find(p=>p.group===r.__group&&p.method===r.method&&p.cluster===r.cluster);return `<tr><td>${esc(r.__branch)}</td><td>${esc(name(r.__group))}</td><td>C${r.cluster+1}</td><td>${esc(p?.representative_branch_id||'—')}</td></tr>`;}).join(''):'<tr><td colspan="4">Aramayla eşleşen şube yok.</td></tr>'}</tbody></table></div></section><details class="card cluster-details"><summary>Deneme ayarları ve bütün k adayları</summary><div class="card-body text-detail"><p>${nf(m.saved_models)} model kaydı yeniden yüklendi. Orman, k adayları, atamalar, büyüklükler, ARI ve profiller doğrulandı. Orijinal yöntemle başlandı; bu belirli ayarların en iyi URF ayarları olduğu iddia edilmez.</p><p>Sayısal aralıklar referans ayda donduruldu. Aralık dışına çıkan değerler mesafede kırpılır; oranlar dağılım raporunda bulunur. K-Prototypes için gamma ${data.settings.gamma}; ayar duyarlılığı ayrıca incelenebilir.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>URF grubu</th><th class="num">Kodlanmış sütun</th><th class="num">mtry</th><th class="num">Gerçek/yapay OOB doğruluğu</th></tr></thead><tbody>${data.summary.filter(r=>r.method==='urf_kmedoids').map(r=>`<tr><td>${esc(name(r.group))}</td><td class="num">${nf(r.encoded_feature_count)}</td><td class="num">${nf(r.effective_mtry)}</td><td class="num">%${nf(r.urf_oob_accuracy*100,1)}</td></tr>`).join('')}</tbody></table></div><p>Gerçek/yapay sınıflar eşit büyüklüktedir; sabit sınıf referansı %50'dir. Bu oran küme doğruluğu değildir. Ayrım zayıfsa URF benzerliği ve kararlılığı ayrıca incelenmelidir.</p><div class="selection-links"><a class="button secondary small" href="downloads/clustering_candidates.csv" download>k adayları</a><a class="button secondary small" href="downloads/clustering_sensitivity.csv" download>Tohum / alt örneklem</a><a class="button secondary small" href="downloads/clustering_drift.csv" download>Aralık dışı değerler</a></div></div></details><p class="inline-note">Bu sentetik, geçmişe dönük karşılaştırmadır; gerçek banka başarısı veya adil hedef dağıtımı kanıtı değildir. Bölgesel koşulların ve kapasitenin etkisi iş profilleriyle değerlendirilmelidir.</p></div>`;
};
window.exportClusteringTable=(data,state)=>{
 data=resolveCase(data,state);
 const columns=['__branch','__period','__group','method','cluster_id'];const rows=[columns,...assignmentRows(data,state).map(r=>columns.map(c=>r[c]))];
 const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='sube_kume_atamalari.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);
};
})();
